float gear(vec3 p,float r) {
    float n = 8.;
    p = radialRepeat(p,n);
    return max(min(roundBox(p,vec3(0,0,.02),r*.4),roundBox(p-vec3(r*.1,0,0),vec3(r*.08,r*.02,.02),.01)),-roundBox(p,vec3(0,0,.1),r*.3));
}
vec4 gear1 (vec3 p,float s) {
    float n = 8.;
    float a = atan(p.y,p.x);
    if (length(p.xy)<0.) a = 0.;
    float x = ceil(a/3.14159/2.*n);
    a = x/n*3.14159*2.;
    p.xy *= ei(a);
    p = p-vec3(.3,0,0);
    x = (mod(x,2.)*2.-1.);
    p = p.zyx;
    p.xy *= ei(s*iTime*x+s*1000.*(.5+.5*x)*3.1459/n);
    return vec4(gear(p,1.),p);
}
vec4 gear2 (vec3 p,float s) {
    float n = 8.;
    float a = atan(p.y,p.x);
    if (length(p.xy)<0.) a = 0.;
    float x = floor(a/3.14159/2.*n);
    a = x/n*3.14159*2.;
    p.xy *= ei(a);
    p = p-vec3(.3,0,0);
    x = (mod(x,2.)*2.-1.);
    p = p.zyx;
    p.xy *= ei(s*(iTime*x+1000.*(.5+.5*x)*3.1459/n));
    return vec4(gear(p,1.),p);
}
