float mino (float d, vec4 g, inout vec3 o) {
    if (g.x<d) {
        d = g.x;
        o = g.yzw;
    }
    return d;
}
vec4 map (vec3 p) {
    float d = 1e4;
    vec3 o = p;

    d = mino(d,gear1(p,1.),o);
    d = mino(d,gear2(p,1.),o);
    p = p.zyx;
    d = mino(d,gear1(p,-1.),o);
    d = mino(d,gear2(p,-1.),o);
    p = p.zxy;
    d = mino(d,gear1(p,-1.),o);
    d = mino(d,gear2(p,-1.),o);
    {
        vec3 q = p;
        q.xy *= ei(3.14159/8.);
        d = mino(d,gear3(q,1.),o);
        d = mino(d,gear4(q,1.),o);
    }
    {
        vec3 q = p.xzy;
        q.xy *= ei(3.14159/8.);
        d = mino(d,gear3(q,1.),o);
        d = mino(d,gear4(q,1.),o);
    }

    {
        vec3 q = p.zyx;
        q.xy *= ei(3.14159/8.);
        d = mino(d,gear3(q,1.),o);
        d = mino(d,gear4(q,1.),o);
    }

    return vec4(d,o);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
Main {

    vec2 u = 1.*(U-.5*R)/R.y;
    vec3 p = vec3(0,0,-1);
    vec3 d = normalize(vec3(u,1));
    p.xz *= ei(.2*iTime);
    d.xz *= ei(.2*iTime);
    p.zy *= ei(.1*iTime);
    d.zy *= ei(.1*iTime);
    float j = 0.;
    for (float i = 0.; i < 30.; i++) {

        float l = map(p).x;
        if(l<.001) break;
        j = i; // Iteration count.
        p += d*l;

    }
    vec4 m = map(p);
    if (m.x>.1) Q = vec4(0);else {
        vec3 o = m.yzw;
        Q = max(1.3 - j/20., 0.)*texture(iChannel1,4.*o.xy)*
        vec4(.8 + max(dot(normal(p), -vec3(.577)), 0.));
    }
    }

#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define R iResolution.xy
#define Main void mainImage(out vec4 Q, in vec2 U)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec4 hash(vec4 p) {
    const vec4 k = vec4(0.1031, 0.11369, 0.13787, 0.16379); 
    p = fract(p * k);                                       
    p += dot(p, p.wxyz + k);                                
    p = fract((p.xxyz + p.yzww) * p.zyxw);                  
    return fract(sin(p) * 43758.5453);                      
}
float ln (vec3 u, vec3 a, vec3 b) {

    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,1.));

}
float ellipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}
float smin( float a, float b, float k )
{
	float h = clamp( 0.5 + 0.5*(b-a)/k, 0.0, 1.0 );
	return mix( b, a, h ) - k*h*(1.0-h);
}
float smax(float a, float b, float k)
{
    return smin(a, b, -k);
}
float subtract (float a, float b) {
    return max(a,-b);
}
float add (float a, float b) {
    return min(a,b);
}
vec3 radialRepeat (vec3 p, inout float n) {

    if (length(p.xy)<0.) return p;
    float a = atan(p.y,p.x);
    float x = round(a/3.14159/2.*n);
    a = x/n*3.14159*2.;
    n = x;
    p.xy *= ei(a);
    return p;

}
vec3 repeat (vec3 p, vec3 n) {
    return 1./n*(fract((n*p*0.5+0.5))*2.-1.);
}
vec4 opElongate( in vec3 p, in vec3 h )
{
    vec3 q = abs(p)-h;
    return vec4( max(q,0.0), min(max(q.x,max(q.y,q.z)),0.0) );
}
float sdCappedCylinder( vec3 p, vec2 h )
{
  vec2 d = abs(vec2(length(p.xy),p.z)) - .25*h;
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}
float roundBox(vec3 p, vec3 b , float r) {
    vec4 w = opElongate( p, .5*b );
    return w.w+sdCappedCylinder( w.xyz, vec2(r,.5*b.z) ) ;
}
float roundBox(vec2 p, vec2 b, float r) {
    return roundBox(vec3(p,0),vec3(b,1),r);
}
